from collections import deque
o=robot.observe('topview'); im=o['rgb'];mask=(im[:,:,0]>100)&(im[:,:,1]<50)&(im[:,:,2]<50)&(np.indices(im.shape[:2])[0]<300)
H,W=mask.shape;seen=np.zeros_like(mask); comps=[]
for y,x in zip(*np.where(mask)):
 if seen[y,x]:continue
 q=[(y,x)];seen[y,x]=1;pts=[]
 while q:
  yy,xx=q.pop();pts.append((yy,xx))
  for Y,X in [(yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)]:
   if 0<=Y<H and 0<=X<W and mask[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
 if len(pts)>2:comps.append(pts)
for c in sorted(comps,key=len,reverse=True)[:10]:print('n',len(c),'centroid',np.mean(c,axis=0)[::-1].round(1),'bbox',(min(x for y,x in c),min(y for y,x in c),max(x for y,x in c),max(y for y,x in c)))
print('tcp',o['robot']['tcp_position'])
